// Local-dev placeholder service worker.
// The REAL production worker is generated by Serwist from src/sw.ts at build
// time (swDest: public/sw.js), so this file is only ever used during local dev.
// It must NOT force-navigate clients — doing so caused reload loops on localhost
// (blank screen / stuck skeletons). Instead it clears caches, unregisters itself,
// and gets out of the way without reloading anything.
self.addEventListener('install', (e) => {
  self.skipWaiting();
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.map((k) => caches.delete(k))))
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil(self.registration.unregister());
});
